+#[test]
+fn degenerate_meridians_are_refused_by_name() {
+    let l = SpunPoint::line;
+    let new = |p: Vec<SpunPoint>| {
+        let n = p.len().saturating_sub(1);
+        Meridian::new(p, vec![true; n])
+    };
+    assert_eq!(new(vec![l(0.0, 0.0)]), Err(MeridianError::TooFew));
+    assert_eq!(new(vec![l(0.0, 0.0), l(0.0, 0.0), l(5.0, 1.0)]), Err(MeridianError::Short(1)));
+    assert_eq!(new(vec![l(0.0, 0.0), l(0.0, -1.0), l(5.0, 1.0)]), Err(MeridianError::Negative(2)));
+    assert_eq!(new(vec![l(0.0, 0.0), l(f64::NAN, 1.0)]), Err(MeridianError::NonFinite(2)));
+    assert_eq!(new(vec![l(0.0, 0.0), arc(0.0, 1.0, f64::INFINITY), l(5.0, 1.0)]), Err(MeridianError::NonFinite(2)));
+    assert_eq!(new(vec![l(0.0, 0.0), arc(0.0, 1.0, 1.0), l(5.0, 1.0)]), Err(MeridianError::ArcTooTight(2)));
+    assert_eq!(new(vec![l(0.0, 0.0), l(5.0, 1.0), l(4.0, 1.0)]), Err(MeridianError::RunsBack(2)));
+    // A convex arc over a flat chord bulges below the tip.
+    assert_eq!(new(vec![arc(0.0, 0.0, 3.0), l(0.0, 5.0)]), Err(MeridianError::ArcFolds(1)));
+    // A concave arc that dips through the axis.
+    assert_eq!(new(vec![arc(0.0, 1.0, -5.0), l(8.0, 1.0)]), Err(MeridianError::Negative(1)));
+    assert_eq!(Meridian::new(vec![l(0.0, 0.0), l(5.0, 1.0)], vec![]), Err(MeridianError::FlagCount));
+    let m = roundover();
+    assert_eq!(m.atoms(Bound::Outer, 0.0), Err(MeridianError::BadSag));
+    assert_eq!(m.atoms(Bound::Inner, f64::NAN), Err(MeridianError::BadSag));
+    assert_eq!(m.atoms(Bound::Outer, 1e-12), Err(MeridianError::SagTooFine(3)));
+}
